      if (!src) return;
      const img = new Image();
      img.onload = () => { el.style.backgroundImage = 'url("' + A(src) + '")'; el.classList.add('has-photo'); };
      img.src = A(src); // gagal dimuat -> tetap tampil placeholder gradien
