  const PHOTOS = { 1: 'foto-meeting.jpg', 2: 'foto-ai.jpg', 3: 'foto-biosains.jpg', 4: 'foto-kunjungan-tani.jpg', 5: 'foto-solar.jpg', 6: 'foto-lab-pelajar.jpg', 7: 'foto-padi.jpg', 8: 'foto-smartfarm.jpg', 9: 'foto-satelit.jpg', 10: 'foto-roket.jpg', 11: 'foto-karang.jpg', 12: 'foto-serah-teknologi.jpg' }; // foto yang tersedia di assets/img/
  const grid = $('#catalogGrid'), chipsWrap = $('#catalogChips'), search = $('#catalogSearch');
